<script setup lang="ts">import{onMounted,ref}from"vue";import{get,post}from"../api";const projects=ref<any[]>([]),name=ref("");async function load(){projects.value=await get("/projects")}async function add(){await post("/projects",{name:name.value});name.value="";load()}onMounted(load);</script><template><h1>项目管理</h1><div class="row"><input v-model="name" placeholder="项目名称"><button @click="add">新建项目</button></div><div class="panel" v-for="project in projects" :key="project.id"><strong>{{project.name}}</strong> · {{project.status}}</div></template>
